import{z as A,x as d,o as n,c as p,q as t,j as s,D as l,d as r,s as E,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Miller–Rabin 素性测试","description":"","frontmatter":{"title":"Miller–Rabin 素性测试","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/miller-rabin.md","filePath":"cs/miller-rabin.md","lastUpdated":1791063341000}'),B={name:"cs/miller-rabin.md"};function m(C,a,h,b,u,c){const i=d("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="miller–rabin-素性测试" tabindex="-1">Miller–Rabin 素性测试 <a class="header-anchor" href="#miller–rabin-素性测试" aria-label="Permalink to &quot;Miller–Rabin 素性测试&quot;">​</a></h1><div class="epigraph"><p>把 $n-1=2^s d$ 写成奇 $d$，检查随机底 $a$ 的平方链是否给出非平凡平方根 $1$；合数至少被 $3/4$ 的底揭穿，重复则错误指数下降。</p><footer>—— 据 Miller, 1976；Rabin, 1980；Knuth, TAOCP 卷 2 整理</footer></div><p>上一课<a href="/cs/quadratic-residue">二次剩余</a> 用过 \\(a^{(p-1)/2}\\)。费马测试被 Carmichael 欺骗。缺口是 <strong>Miller–Rabin</strong>：强伪素见证。主干随机算法课点名素性，未写数论。本课 Monte Carlo：是素数永不误判为合？否——方向：合数可能被当成素（单侧），重复压错误。AKS 在 P，实践仍用 MR。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 奇。写 \\(n-1=2^sd\\)。若 \\(n\\) 素，则 \\(a^d\\equiv 1\\) 或某 \\(a^{2^rd}\\equiv -1\\pmod n\\)（在到达 \\(1\\) 之前）。否则 \\(a\\) 是合数见证。Rabin：至多 \\(1/4\\) 的 \\(a\\) 对合数说谎。\\(k\\) 次独立，\\(4^{-k}\\)。确定性 Miller 在广义 Riemann 假设下把底限制到 \\(O((\\log n)^2)\\)，本课点名。</p><p>Carmichael 数通过费马，多数过不了 MR 的平方链。</p><h3 id="不是分解算法" tabindex="-1">不是分解算法 <a class="header-anchor" href="#不是分解算法" aria-label="Permalink to &quot;不是分解算法&quot;">​</a></h3><p>输出「可能是素 / 合数见证」。合数见证不给出因子。分解是另一问题。</p><p><span class="marginnote">Miller 1976（GRH 下确定）；Rabin 1980 随机。Knuth 卷 2。Damgård–Landrock–Pomerance 的错误界更细，课堂用 \\(1/4\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对小合数 \\(n=91\\) 找一个见证。写清算法步骤。对照<a href="/cs/bpp-randomized-class">BPP</a>：MR 是 RP 形状（合数有许多见证）。素数生成下一课：随机抽奇数再 MR。</p><p><span class="marginnote">数字实例：\\(n=91=7\\times13\\)，\\(n-1=90=2^1\\times45\\)。取 \\(a=2\\)：\\(2^{45}\\bmod 91=57\\)，既不是 \\(1\\) 也不是 \\(90\\)；平方一次得 \\(64\\)，始终没遇到 \\(90\\)——此底是见证，\\(91\\) 判为合数。Carmichael 数骗得过费马，多数骗不过这条平方链。</span></p>',12)),(n(),s(o,null,{default:l(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%A5%87%E6%95%B0%20n%22%5D%20--%3E%20SPLIT%5B%22n-1%3D2%5Es%20d%22%5D%0A%20%20SPLIT%20--%3E%20CHAIN%5B%22a%5Ed%20%E5%86%8D%E5%B9%B3%E6%96%B9%22%5D%0A%20%20CHAIN%20--%3E%20WIT%5B%22%E8%A7%81%E8%AF%81%E5%90%88%E6%95%B0%20%2F%20%E5%8F%AF%E8%83%BD%E7%B4%A0%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了单侧错误的素性测试，密码才能在多项式时间内抽样「看起来像素数」的整数。错误 \\(4^{-k}\\) 可小于硬件故障率。确定性 AKS 多项式次数高，不替代本课。",-1)),a[5]||(a[5]=e("p",null,"不要用费马测试当生产实现。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：MR 像机场安检的随机抽查——素数永远不会被误抓（单侧错误），合数每轮至少 \\(3/4\\) 的抽查项会露馅；抽查 \\(k\\) 轮，漏网概率不超过 \\(4^{-k}\\)，查 20 轮就已低于万亿分之一，比硬件随机翻转还罕见。")],-1)),(n(),s(o,null,{default:l(()=>[E(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20POW%5B%22%E7%AE%97%20x%20%3D%20a%5Ed%20mod%20n%22%5D%20--%3E%20T1%7B%22x%20%E6%98%AF%201%20%E6%88%96%20n-1%3F%22%7D%0A%20%20T1%20--%3E%7C%22%E6%98%AF%22%7C%20PASS%5B%22%E6%9C%AC%E5%BA%95%E9%80%9A%E8%BF%87%2C%20%E6%8D%A2%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%BA%95%22%5D%0A%20%20T1%20--%3E%7C%22%E5%90%A6%22%7C%20SQ%5B%22x%20%E8%87%AA%E4%B9%98%E5%8F%96%E6%A8%A1%3A%20x%20%3D%20x%5E2%20mod%20n%22%5D%0A%20%20SQ%20--%3E%20T2%7B%22x%20%E5%8F%98%E6%88%90%20n-1%20%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20T2%20--%3E%7C%22%E6%98%AF%22%7C%20PASS2%5B%22%E6%9C%AC%E5%BA%95%E9%80%9A%E8%BF%87%22%5D%0A%20%20T2%20--%3E%7C%22%E5%90%A6%2C%20%E4%B8%94%E6%9C%AA%E5%B9%B3%E6%96%B9%E6%BB%A1%20s%20%E6%AC%A1%22%7C%20SQ%0A%20%20T2%20--%3E%7C%22%E5%B9%B3%E6%96%B9%E6%BB%A1%20s%20%E6%AC%A1%E4%BB%8D%E6%9C%AA%E9%81%87%20n-1%22%7C%20WIT%5B%22%E6%9C%AC%E5%BA%95%E6%98%AF%E8%A7%81%E8%AF%81%3A%20n%20%E5%BF%85%E4%B8%BA%E5%90%88%E6%95%B0%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>确定性界：对 \\(n\\lt 2^{64}\\) 用固定底集合即可（实现表），课堂仍讲随机。强伪素数相对某底通过 MR，必须换底。AKS 是多项式确定，次数高。ECPP 给证明证书，验证快于再跑 MR。生产密钥生成走下一课的抽样 + 本课检验。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 \\(1/4\\) 界，不写 AKS。不引入椭圆曲线素性证明（ECPP）全文。后课默认：实践素性 = 重复 Miller–Rabin。下一课素数分布与生成。</p><p>单侧错误：素数永不被判合；合数以 \\(\\le 1/4\\) 概率骗过一轮。重复独立即可压到可忽略。它不输出因子。生成密钥是抽样问题，下一课用素数定理估次数。</p><p><span class="marginnote">常见误区：以为素性测试能顺便给出因子。MR 只回答「n 一定不是素（附见证）」或「n 大概率是素」，见证本身不含任何因子信息；把大数拆开是分解问题，难度天差地别——RSA 的安全正建立在这道鸿沟上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MR：平方链查非平凡根 \\(1\\)；合数 \\(\\le 1/4\\) 底说谎。</li><li>单侧 Monte Carlo；重复指数压错误。</li><li>不分解；强于费马测试。</li><li>出处：Miller, 1976；Rabin, 1980；Knuth。</li></ul>',7))])}const R=A(B,[["render",m]]);export{T as __pageData,R as default};
